package com.quickcart.service; import com.quickcart.entity.*; import com.quickcart.repository.*; import com.quickcart.dto.AddressRequest; import com.quickcart.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CustomerService {final CustomerRepository customers;final AddressRepository addresses;CustomerService(CustomerRepository c,AddressRepository a){customers=c;addresses=a;} public Customer get(Long id){return customers.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Customer not found"));} public Customer create(String name,String mobile,String email){return customers.save(new Customer(null,name,mobile,email,null,null));} public Address add(Long cid,AddressRequest r){Customer c=get(cid);Address a=new Address(null,c,r.fullName(),r.mobile(),r.house(),r.street(),r.area(),r.city(),r.state(),r.pincode(),r.latitude(),r.longitude(),r.isDefault());return addresses.save(a);} public List<Address> list(Long cid){return addresses.findByCustomerId(cid);} }
